def _tail_generated() -> Dict[str, Gloss]:
    from src.astadhyayi.nipata import PROVISIONS

    out: Dict[str, Gloss] = {}
    for provision in PROVISIONS:
        if provision.sutra in GLOSSES:
            continue
        _deva, _, english = provision.gloss.partition(" — ")
        names = " and ".join(sorted(n.value for n in provision.gives))
        plain = (
            f"{english[:1].upper()}{english[1:]} — "
            f"so it is called {names}."
        )
        if provision.optional:
            plain += " Optionally."
        shown = []
        if provision.example:
            shown.append(f"{iast_to_devanagari(provision.example)} "
                         f"{provision.example}")
        if provision.counter:
            shown.append(f"but {iast_to_devanagari(provision.counter)} "
                         f"{provision.counter}")
        out[provision.sutra] = Gloss(plain, " · ".join(shown))
    return out


