def gloss_for(sutra_id: str) -> Optional[Gloss]:
    return GLOSSES.get(sutra_id)


__all__ = ["CONDITION_GLOSS", "GLOSSES", "Gloss", "SENSE_GLOSS", "gloss_for"]


# Applied last, so that hand-written entries, generated entries and anything
# added later all reach a reader in the same shape.
GLOSSES.update({
    key: in_one_shape(gloss) for key, gloss in GLOSSES.items()
})
